package cn.local.gaokao;
import android.app.AlertDialog;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Local collections are independent of grades and are preserved by learning reset. */
final class WordBooks {
 final MainActivity a;WordBooks(MainActivity a){this.a=a;}
 static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS word_book(id TEXT PRIMARY KEY,name TEXT NOT NULL,created INTEGER NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS word_book_entry(book TEXT NOT NULL,word TEXT NOT NULL,added INTEGER NOT NULL,PRIMARY KEY(book,word))");db.execSQL("INSERT OR IGNORE INTO word_book VALUES('default','生词本',0)");}
 int countRows(String sql,String...args){try(Cursor c=a.store.getReadableDatabase().rawQuery(sql,args)){c.moveToFirst();return c.getInt(0);}}
 int count(){return countRows("SELECT count(*) FROM word_book");}
 boolean saved(String word){return countRows("SELECT count(*) FROM word_book_entry WHERE word=?",word)>0;}
 void chooseTerm(String word,Runnable after){ArrayList<String> ids=new ArrayList<>(),names=new ArrayList<>();ArrayList<Boolean> states=new ArrayList<>();try(Cursor c=a.store.getReadableDatabase().rawQuery("SELECT id,name FROM word_book ORDER BY created,id",null)){while(c.moveToNext()){ids.add(c.getString(0));names.add(c.getString(1));states.add(countRows("SELECT count(*) FROM word_book_entry WHERE book=? AND word=?",c.getString(0),word)>0);}}boolean[] checked=new boolean[states.size()];for(int i=0;i<checked.length;i++)checked[i]=states.get(i);new AlertDialog.Builder(a).setTitle("收藏「"+word+"」").setMultiChoiceItems(names.toArray(new String[0]),checked,(d,n,on)->checked[n]=on).setPositiveButton("保存",(d,w)->{SQLiteDatabase db=a.store.getWritableDatabase();db.beginTransaction();try{for(int i=0;i<ids.size();i++){db.delete("word_book_entry","book=? AND word=?",new String[]{ids.get(i),word});if(checked[i])db.execSQL("INSERT INTO word_book_entry VALUES(?,?,?)",new Object[]{ids.get(i),word,System.currentTimeMillis()});}db.setTransactionSuccessful();}finally{db.endTransaction();}if(after!=null)after.run();}).setNeutralButton("新建词书",(d,w)->newBook(word,after)).setNegativeButton("取消",null).show();}
 void newBook(String word,Runnable after){newBook(word,null,after);}
 void newBook(String word,JSONObject example,Runnable after){EditText input=new EditText(a);input.setSingleLine();input.setHint("词书名称");AlertDialog dialog=new AlertDialog.Builder(a).setTitle("新建词书").setView(input).setPositiveButton("创建",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{String name=input.getText().toString().trim();if(name.isEmpty()||name.length()>30){input.setError("请输入1至30字的名称");return;}String id=UUID.randomUUID().toString();SQLiteDatabase db=a.store.getWritableDatabase();db.beginTransaction();try{db.execSQL("INSERT INTO word_book VALUES(?,?,?)",new Object[]{id,name,System.currentTimeMillis()});if(example!=null)ExampleCollections.put(db,id,word,example);else if(word!=null)db.execSQL("INSERT INTO word_book_entry VALUES(?,?,?)",new Object[]{id,word,System.currentTimeMillis()});db.setTransactionSuccessful();}finally{db.endTransaction();}dialog.dismiss();if(after!=null)after.run();else show();}));dialog.show();}
 void show(){a.screen("wordBooks");a.childHeader("单词本",a::library);((android.view.ViewGroup)a.currentCanvas).getChildAt(0).setVisibility(android.view.View.GONE);a.currentCanvas.setBackgroundColor(0xffffffff);a.dock.setVisibility(android.view.View.GONE);a.note("默认单词本");boolean custom=false;try(Cursor c=a.store.getReadableDatabase().rawQuery("SELECT id,name FROM word_book ORDER BY created,id",null)){while(c.moveToNext()){String id=c.getString(0),name=c.getString(1);boolean primary=id.equals("default");if(!primary&&!custom){custom=true;a.note("自建单词本 "+(count()-1)+" 本");}bookRow(id,name,primary,false);}}bookRow(null,"新建词书",false,true);}
 void bookRow(String id,String name,boolean primary,boolean add){LinearLayout row=new LinearLayout(a);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setPadding(0,a.dp(14),0,a.dp(18));row.addView(new Cover(primary,add),new LinearLayout.LayoutParams(a.dp(52),a.dp(70)));LinearLayout labels=new LinearLayout(a);labels.setOrientation(1);labels.setPadding(a.dp(20),0,0,0);TextView title=new TextView(a);title.setText(name);title.setTextSize(20);title.setTextColor(add?a.GREEN:a.INK);title.setTypeface(null,android.graphics.Typeface.BOLD);labels.addView(title);if(!add){TextView amount=new TextView(a);amount.setText(countRows("SELECT count(*) FROM word_book_entry WHERE book=?",id)+" 词 · "+countRows("SELECT count(*) FROM word_book_example WHERE book=?",id)+" 句");amount.setTextSize(14);amount.setTextColor(a.MUTED);amount.setPadding(0,a.dp(22),0,0);labels.addView(amount);}row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));if(!primary&&!add){Button more=a.action("⋮",()->manage(id,name));more.setContentDescription("管理词书 "+name);more.setMinWidth(0);row.addView(more,new LinearLayout.LayoutParams(a.dp(40),a.dp(48)));}row.setOnClickListener(v->{if(add)newBook(null,this::show);else entries(id,name);});row.setContentDescription(name);a.root.addView(row,new LinearLayout.LayoutParams(-1,-2));}
 final class Cover extends android.view.View {final boolean primary,add;final android.graphics.Paint pen=new android.graphics.Paint(3);Cover(boolean primary,boolean add){super(a);this.primary=primary;this.add=add;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
 protected void onDraw(android.graphics.Canvas canvas){float sx=getWidth()/52f,sy=getHeight()/70f;canvas.save();canvas.scale(sx,sy);pen.setStyle(android.graphics.Paint.Style.FILL);pen.setColor(add?0xffffffff:primary?0xfff05656:0xff69cedd);canvas.drawRoundRect(3,1,51,69,3,3,pen);if(add){pen.setStyle(android.graphics.Paint.Style.STROKE);pen.setColor(0xffdddddd);pen.setStrokeWidth(1);canvas.drawRoundRect(1,1,51,69,3,3,pen);pen.setColor(0xff999999);pen.setStrokeWidth(1.5f);canvas.drawLine(21,35,31,35,pen);canvas.drawLine(26,30,26,40,pen);}else{pen.setColor(0xffffffff);pen.setTextSize(9);pen.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);canvas.drawText(primary?"生词本":"古文",primary?12:17,17,pen);pen.setStyle(android.graphics.Paint.Style.STROKE);pen.setStrokeWidth(2);for(int i=0;i<5;i++)canvas.drawOval(0,23+i*8,7,27+i*8,pen);if(primary){pen.setColor(0xffffcb63);pen.setStyle(android.graphics.Paint.Style.FILL);android.graphics.Path star=new android.graphics.Path();for(int n=0;n<10;n++){double angle=-Math.PI/2+n*Math.PI/5;float radius=n%2==0?20:9,x=37+(float)Math.cos(angle)*radius,y=51+(float)Math.sin(angle)*radius;if(n==0)star.moveTo(x,y);else star.lineTo(x,y);}star.close();canvas.drawPath(star,pen);}else{pen.setColor(0xff36a9be);pen.setStrokeWidth(1);for(int i=0;i<3;i++)canvas.drawLine(15,33+i*9,40,33+i*9,pen);}}canvas.restore();}}
 void manage(String id,String name){new AlertDialog.Builder(a).setItems(new String[]{"重命名","删除词书"},(d,n)->{if(n==0)rename(id,name);else new AlertDialog.Builder(a).setTitle("删除「"+name+"」？").setMessage("仅删除收藏分组，不改变学习记录。").setPositiveButton("删除",(x,w)->{SQLiteDatabase db=a.store.getWritableDatabase();db.beginTransaction();try{db.delete("word_book_example","book=?",new String[]{id});db.delete("word_book_entry","book=?",new String[]{id});db.delete("word_book","id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}show();}).setNegativeButton("取消",null).show();}).show();}

 void entries(String id,String name){a.screen("wordBookEntries");a.childHeader(name,this::show);try(Cursor c=a.store.getReadableDatabase().rawQuery("SELECT word FROM word_book_entry WHERE book=? ORDER BY added DESC,word",new String[]{id})){while(c.moveToNext()){String word=c.getString(0);Button row=a.button(word,()->new DictionaryPanel(a,()->entries(id,name)).detail(word));row.setOnLongClickListener(v->{new AlertDialog.Builder(a).setTitle("移出「"+word+"」？").setPositiveButton("移出",(d,w)->{a.store.getWritableDatabase().delete("word_book_entry","book=? AND word=?",new String[]{id,word});entries(id,name);}).setNegativeButton("取消",null).show();return true;});}}new ExampleCollections(a).rows(id,name);if(!id.equals("default"))a.button("管理词书",()->manage(id,name));}

 void rename(String id,String name){EditText input=new EditText(a);input.setSingleLine();input.setText(name);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("重命名词书").setView(input).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{String s=input.getText().toString().trim();if(s.isEmpty()||s.length()>30){input.setError("请输入1至30字的名称");return;}ContentValues value=new ContentValues();value.put("name",s);a.store.getWritableDatabase().update("word_book",value,"id=?",new String[]{id});dialog.dismiss();entries(id,s);}));dialog.show();}
}
